rows: dict[str, tuple[tuple[str, ...], list[tuple]]] = {}


def add(table, cols, *vals):
    rows.setdefault(table, (cols, []))[1].append(vals)


def uid(kind, n):
    return f"00000000-0000-0000-{kind:04d}-{n:012d}"


def sql(v):
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, (int, float)):
        return repr(v)
    if isinstance(v, datetime):
        return f"'{v:%Y-%m-%d %H:%M:%S}'"
    if isinstance(v, list):
        return "ARRAY[" + ",".join(sql(x) for x in v) + "]"
    return "'" + str(v).replace("'", "''") + "'"


def bell(mu, sigma, lo=0.0, hi=1.0):
    return min(hi, max(lo, random.gauss(mu, sigma)))


def activity_time(lo, hi):
    """Weekday- and hour-weighted timestamp between lo and hi."""
    if hi < lo:
        raise ValueError("activity interval ends before it starts")
    while True:
        t = lo + timedelta(seconds=random.uniform(0, (hi - lo).total_seconds()))
        if random.random() > [0.9, 1.0, 1.0, 0.95, 0.7, 0.3, 0.35][t.weekday()]:
            continue
        # Reject quiet hours rather than replacing the hour, which can leave the interval.
        if random.random() < (1.0 if 9 <= t.hour <= 21 else 0.15):
            assert lo <= t <= hi
            return t


