# assignments, submissions, grades
task_n = sub_n = grade_n = notif_n = 0
for c in range(1, 4):
    weeks = [4, 8, 12] if c == 1 else [5, 10]
    for i, w in enumerate(weeks, start=1):
        task_n += 1
        tu, fu = uid(9, task_n), uid(10, task_n)
        due = START + timedelta(weeks=w, days=6, hours=15, minutes=59)
        add("task", ("uuid", "course_section_uuid", "name"), tu, sections[c][min(i, 3)], f"Übungsblatt {i}")
        group_mode = i == 2
        add("file_upload", ("uuid", "task_uuid", "title", "max_points", "due_date", "cut_off_date",
                            "group_mode", "grouping_uuid"),
            fu, tu, f"Abgabe Übungsblatt {i}", 10.0, due, due + timedelta(days=2),
            group_mode, groupings[c] if group_mode else None)
        # A group assignment is handed in once per group, by one of its members.
        if group_mode:
            handins = [(random.choice(ms), gu, ms) for gu, ms in groups[c] if ms]
        else:
            handins = [(m, None, [m]) for m in enrolled[c]]
        for m, gu, credited in handins:
            if random.random() > 0.85:
                continue
            late = random.random() < 0.08
            at = due + timedelta(hours=random.uniform(0.5, 30)) if late else due - timedelta(hours=168 * random.random() ** 3)
            sub_n += 1
            add("submission", ("uuid", "file_upload_uuid", "submitter_uuid", "group_uuid", "file_refs", "submitted_at"),
                uid(11, sub_n), fu, users[m], gu, [f"/submissions/{sub_n}.pdf"], at)
            if random.random() < (0.95 if due < datetime(2026, 7, 1) else 0.4):
                grade_n += 1
                points = round(10 * bell(0.72, 0.18) * 2) / 2
                graded = at + timedelta(days=random.randint(3, 10), hours=random.randint(8, 18))
                add("grade", ("uuid", "grader_uuid", "submission_uuid", "attempt_uuid",
                              "question_uuid", "points", "feedback", "graded_at"),
                    uid(12, grade_n), users[random.choice([PROFS[c - 1], HIWIS[c % 2]])], uid(11, sub_n),
                    None, None, points, random.choice(FEEDBACK), graded)
                for r in credited:
                    notif_n += 1
                    add("notification", ("uuid", "recipient_uuid", "type", "payload", "created_at", "read_at"),
                        uid(19, notif_n), users[r], "grade", f'{{"submission_uuid": "{uid(11, sub_n)}", "points": {points}}}',
                        graded, graded + timedelta(hours=random.randint(1, 72)) if random.random() < 0.7 else None)

# question bank, quizzes, attempts
