questions: dict[int, list[tuple[str, list[tuple[str, float]], float, int]]] = {}
free_text: dict[int, list[str]] = {}
for c in range(1, 4):
    questions[c] = []
    free_text[c] = []
    bank = DBS_QUESTIONS
    if c != 1:
        bank = []
        for k in range(1, 11):
            fr = [1.0, 0.0, 0.0, 0.0]
            random.shuffle(fr)
            bank.append((f"Frage {k} zu {COURSES[c - 1][2][1 + k % 3]}", [(f"Antwort {l}", f) for l, f in zip("ABCD", fr)]))
    for body, opts in bank:
        q_n += 1
        qu = uid(13, q_n)
        add("question", ("uuid", "course_uuid", "body", "type", "default_points"), qu, uid(6, c), body, "mcq", 2.5)
        ous = []
        for pos, (text, fraction) in enumerate(opts, start=1):
            opt_n += 1
            ous.append((uid(14, opt_n), fraction))
            add("question_option", ("uuid", "question_uuid", "position", "body", "fraction"), uid(14, opt_n), qu, pos, text, fraction)
        wrong = [i for i, (_, f) in enumerate(ous) if f == 0]
        questions[c].append((qu, ous, random.uniform(0.35, 0.9), random.choice(wrong)))
    for body in FREE_TEXT[c]:
        q_n += 1
        free_text[c].append(uid(13, q_n))
        add("question", ("uuid", "course_uuid", "body", "type", "default_points"),
            uid(13, q_n), uid(6, c), body, "free_text", 2.5)

    for qi in range(2 if c == 1 else 1):
        task_n += 1
        quiz_n += 1
        tu, qzu = uid(9, task_n), uid(15, quiz_n)
        opens = START + timedelta(weeks=6 + 5 * qi)
        add("task", ("uuid", "course_section_uuid", "name"), tu, sections[c][2 + qi % 2], f"Quiz {qi + 1}")
        add("quiz", ("uuid", "task_uuid", "title", "time_limit", "available_from", "available_until",
                     "attempts_allowed", "grading_method"),
            qzu, tu, f"Quiz {qi + 1}: {COURSES[c - 1][2][1 + qi]}", 30, opens, opens + timedelta(days=10), 2,
            GRADING_METHODS[(quiz_n - 1) % len(GRADING_METHODS)])
        used = questions[c][qi * 2:qi * 2 + 7]
        written = free_text[c][qi]
        for pos, (qu, *_) in enumerate(used, start=1):
            add("quiz_question", ("quiz_uuid", "question_uuid", "position", "points"), qzu, qu, pos, 2.5)
        add("quiz_question", ("quiz_uuid", "question_uuid", "position", "points"),
            qzu, written, len(used) + 1, 2.5)
        for m in enrolled[c]:
            if random.random() > 0.85:
                continue
            for attempt in range(2 if random.random() < 0.35 else 1):
                att_n += 1
                au = uid(16, att_n)
                started = opens + timedelta(days=random.uniform(0.2, 9.5) if attempt == 0 else random.uniform(5, 9.8))
                # A few attempts are still open when the snapshot is taken.
                in_progress = random.random() < 0.06
                add("quiz_attempt", ("uuid", "quiz_uuid", "student_uuid", "started_at", "submitted_at"),
                    au, qzu, users[m], started,
                    None if in_progress else started + timedelta(minutes=random.randint(8, 28)))
                add("quiz_answer_text", ("attempt_uuid", "question_uuid", "free_text"),
                    au, written, random.choice(FREE_TEXT_ANSWERS))
                # Free text is marked by hand, so some answers have no grade yet.
                if not in_progress and random.random() < 0.75:
                    grade_n += 1
                    add("grade", ("uuid", "grader_uuid", "submission_uuid", "attempt_uuid",
                                  "question_uuid", "points", "feedback", "graded_at"),
                        uid(12, grade_n), users[random.choice([PROFS[c - 1], HIWIS[c % 2]])],
                        None, au, written, round(2.5 * bell(0.7, 0.25) * 2) / 2,
                        random.choice(FEEDBACK), started + timedelta(days=random.randint(2, 9)))
                for qu, ous, difficulty, distractor in used:
                    p = min(0.95, difficulty + 0.2 * attempt)
                    fractions = [f for _, f in ous]
                    multi = max(fractions) < 1.0
                    best = [i for i, f in enumerate(fractions) if f > 0] if multi else [fractions.index(max(fractions))]
                    if random.random() < p:
                        picks = best
                    elif random.random() < 0.6:
                        picks = [distractor]
                    else:
                        picks = [random.choice([i for i in range(len(ous)) if i not in best])]
                    for i in sorted(set(picks)):
                        add("quiz_answer_option", ("attempt_uuid", "selected_option_uuid"), au, ous[i][0])

