with OUT.open("w", encoding="utf-8") as f:
    f.write("-- Generated by gen_seed.py; regenerate instead of editing.\n"
            "-- Import once into a fresh migrated database, as one transaction.\n\n")
    # grade references quiz_answer_text, so it is written last.
    for table in [t for t in rows if t != "grade"] + ["grade"]:
        cols, values = rows[table]
        f.write(f"INSERT INTO {table} ({', '.join(cols)}) VALUES\n")
        f.write(",\n".join("  (" + ", ".join(sql(v) for v in vals) + ")" for vals in values))
        f.write(";\n\n")

print(f"{OUT.name}: " + ", ".join(f"{t.strip(chr(34))} {len(v)}" for t, (_, v) in rows.items()))
